import jax.numpy as jnp
import flax.linen as nn
from jax import random
from typing import Dict, Any

def _define_hyperparameters():
    return {
        'learning_rate': 0.001,
        'hidden_dim': 128,
        'dropout_rate': 0.1,
        'kernel_size': 8
    }

class ReverseComplementCNN(nn.Module):
    """A 1D CNN that enforces reverse complement equivariance."""
    d_output: int
    task_type: str
    hidden_dim: int
    dropout_rate: float
    kernel_size: int

    @nn.compact
    def __call__(self, x, deterministic=True):
        # x shape: (batch, seq_len, 4) where channels are A, U, C, G

        # 1. Create Reverse Complement
        # Reverse sequence dimension
        x_rev = jnp.flip(x, axis=1)
        # Swap complementary base channels (A<->U, C<->G)
        # Indices: 0<->1, 2<->3
        x_rc = x_rev[:, :, [1, 0, 3, 2]]

        # 2. Define the shared CNN feature extractor
        cnn_extractor = nn.Sequential([
            nn.Conv(features=self.hidden_dim, kernel_size=(self.kernel_size,)),
            nn.relu,
            lambda seq: jnp.max(seq, axis=1)
        ])

        # 3. Process both original and RC through the same CNN
        features_orig = cnn_extractor(x)
        features_rc = cnn_extractor(x_rc)

        # 4. Average the feature representations
        combined_features = (features_orig + features_rc) / 2.0

        # 5. Final prediction head
        x = nn.Dropout(rate=self.dropout_rate)(combined_features, deterministic=deterministic)
        x = nn.Dense(self.d_output)(x)

        if self.task_type == "regression":
            return x.squeeze(-1)
        else:
            return x

class NetworkWrapper:
    def __init__(self, **kwargs):
        self.network = ReverseComplementCNN(**kwargs)

    def init(self, rng_key, dummy_input):
        params_key, dropout_key = random.split(rng_key)
        variables = self.network.init({'params': params_key, 'dropout': dropout_key},
                                     dummy_input, deterministic=True)
        return variables['params']

    def apply(self, params, x, deterministic=True, rng_key=None):
        if deterministic:
            return self.network.apply({'params': params}, x, deterministic=True)
        else:
            if rng_key is None:
                rng_key = random.PRNGKey(0)
            return self.network.apply({'params': params}, x, deterministic=False,
                                    rngs={'dropout': rng_key})

def create_network(hparams: Dict[str, Any]):
    return NetworkWrapper(
        d_output=hparams["d_output"],
        task_type=hparams["task_type"],
        hidden_dim=hparams["hidden_dim"],
        dropout_rate=hparams["dropout_rate"],
        kernel_size=hparams["kernel_size"]
    )
